// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.addToBalance{value: 1 ether}();
        vm.prank(user);
        c.addToBalance{value: 2 ether}();
        assert(c.getBalance(user) == 3 ether);
    }
}
